<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('admin');if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$id=(int)$_POST['id'];$status=$_POST['status']??'';$ket=trim($_POST['keterangan']??'');if(in_array($status,['menunggu','diproses','selesai','ditolak'],true)){$s=$koneksi->prepare('SELECT status,id_user,nama_barang FROM laporan WHERE id_laporan=?');$s->bind_param('i',$id);$s->execute();$old=$s->get_result()->fetch_assoc();if($old){$s=$koneksi->prepare('UPDATE laporan SET status=? WHERE id_laporan=?');$s->bind_param('si',$status,$id);$s->execute();$admin=(int)currentUser()['id_user'];$s=$koneksi->prepare('INSERT INTO riwayat(id_laporan,id_admin,status_lama,status_baru,keterangan) VALUES(?,?,?,?,?)');$s->bind_param('iisss',$id,$admin,$old['status'],$status,$ket);$s->execute();notifyUser($koneksi,(int)$old['id_user'],'Status laporan diperbarui','Laporan '.$old['nama_barang'].' kini berstatus '.statusLabel($status),'siswa/laporan_saya.php');flash('Status laporan diperbarui.');}}redirect('admin/laporan.php');}$pageTitle='Manajemen Laporan';$rows=$koneksi->query('SELECT l.*,u.nama,k.nama_kategori,lo.nama_lokasi FROM laporan l JOIN users u ON u.id_user=l.id_user JOIN kategori k ON k.id_kategori=l.id_kategori JOIN lokasi lo ON lo.id_lokasi=l.id_lokasi ORDER BY l.created_at DESC');require __DIR__.'/../includes/header.php';?><div class="panel"><div class="panel-head"><div><h2>Semua laporan</h2><small class="muted">Periksa laporan dan perbarui status penanganannya.</small></div><span class="badge"><?=$rows->num_rows?> laporan</span></div><div class="table-wrap"><table><tr><th>Barang / Pelapor</th><th>Jenis</th><th>Lokasi</th><th>Status</th><th>Ubah status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><div style="display:flex;align-items:center;gap:10px"><?php if(!empty($r['foto_barang'])): ?><img src="<?=e(url('uploads/barang/'.$r['foto_barang']))?>" alt="Foto <?=e($r['nama_barang'])?>" style="width:48px;height:48px;object-fit:cover;border-radius:12px;border:1px solid var(--line)"><?php endif; ?><div><b><?=e($r['nama_barang'])?></b><br><small class="muted"><?=e($r['nama'])?> · <?=e($r['nama_kategori'])?></small></div></div></td><td><?=e(ucfirst($r['jenis_laporan']))?></td><td><?=e($r['nama_lokasi'])?></td><td><span class="badge <?=e($r['status'])?>"><?=e(statusLabel($r['status']))?></span></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id" value="<?=$r['id_laporan']?>"><select name="status" class="search" style="width:115px;padding:7px"><?php foreach(['menunggu','diproses','selesai','ditolak'] as $st):?><option value="<?=$st?>" <?=$r['status']===$st?'selected':''?>><?=e(ucfirst($st))?></option><?php endforeach;?></select><button class="btn sm">Simpan</button></form></td></tr><?php endwhile;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
